ea:ConvergentValidity rdfs:subClassOf ea:ConstructValidity ;
  rdfs:comment "The degree to which two measures of constructs that theoretically should be related are, in fact, related." .
ea:DiscriminantValidity rdfs:subClassOf ea:ConstructValidity ;
  rdfs:comment "Tests whether concepts or measurements that are supposed to be unrelated are, in fact, unrelated." .
ea:ConvergentValidity owl:disjointWith ea:DiscriminantValidity .

